<?xml version="1.0" encoding="UTF-8"?>
<project xmlns="http://maven.apache.org/POM/4.0.0"
         xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"
         xsi:schemaLocation="http://maven.apache.org/POM/4.0.0 https://maven.apache.org/xsd/maven-4.0.0.xsd">
    <modelVersion>4.0.0</modelVersion>

    <groupId>com.example</groupId>
    <artifactId>app</artifactId>
    <version>1.0.0-SNAPSHOT</version>
    <packaging>jar</packaging>

    <properties>
        <maven.compiler.release>25</maven.compiler.release>
        <project.build.sourceEncoding>UTF-8</project.build.sourceEncoding>

        <lombok.version>1.18.48</lombok.version>
        <junit.version>6.1.3</junit.version>
        <maven-compiler-plugin.version>3.16.0</maven-compiler-plugin.version>
        <maven-surefire-plugin.version>3.6.0</maven-surefire-plugin.version>
    </properties>

    <dependencyManagement>
        <dependencies>
            <dependency>
                <groupId>org.junit</groupId>
                <artifactId>junit-bom</artifactId>
                <version>${junit.version}</version>
                <type>pom</type>
                <scope>import</scope>
            </dependency>
        </dependencies>
    </dependencyManagement>

    <dependencies>
        <!-- Lombok is compile-time only; it is not needed at runtime. -->
        <dependency>
            <groupId>org.projectlombok</groupId>
            <artifactId>lombok</artifactId>
            <version>${lombok.version}</version>
            <scope>provided</scope>
        </dependency>

        <dependency>
            <groupId>org.junit.jupiter</groupId>
            <artifactId>junit-jupiter</artifactId>
            <scope>test</scope>
        </dependency>
    </dependencies>

    <build>
        <plugins>
            <plugin>
                <groupId>org.apache.maven.plugins</groupId>
                <artifactId>maven-compiler-plugin</artifactId>
                <version>${maven-compiler-plugin.version}</version>
                <configuration>
                    <!-- JDK 23+ no longer discovers annotation processors on the classpath
                         automatically, so Lombok must be declared explicitly here. -->
                    <annotationProcessorPaths>
                        <path>
                            <groupId>org.projectlombok</groupId>
                            <artifactId>lombok</artifactId>
                            <version>${lombok.version}</version>
                        </path>
                    </annotationProcessorPaths>
                </configuration>
            </plugin>
            <plugin>
                <groupId>org.apache.maven.plugins</groupId>
                <artifactId>maven-surefire-plugin</artifactId>
                <version>${maven-surefire-plugin.version}</version>
            </plugin>
        </plugins>
    </build>
</project>
EOF
cat > lombok.config <<'EOF'
# Stop Lombok config lookup from walking above the project root.
config.stopBubbling = true
# Mark generated code with @lombok.Generated so coverage tools (e.g. JaCoCo) ignore it.
lombok.addLombokGeneratedAnnotation = true
EOF
cat > src/main/java/com/example/model/User.java <<'EOF'
package com.example.model;

import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * Example entity: {@code @Data} generates getters, setters, equals/hashCode and toString;
 * the constructor annotations and {@code @Builder} cover object creation.
 */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class User {
    private Long id;
    private String name;
    private String email;
}
EOF
cat > src/main/java/com/example/model/Address.java <<'EOF'
package com.example.model;

import lombok.Value;

/** Immutable example: {@code @Value} makes fields private final and generates an all-args constructor and getters. */
@Value
public class Address {
    String street;
    String city;
}
EOF
cat > src/test/java/com/example/model/UserTest.java <<'EOF'
package com.example.model;

import static org.junit.jupiter.api.Assertions.assertEquals;

import org.junit.jupiter.api.Test;

class UserTest {

    @Test
    void lombokGeneratesAccessorsConstructorsAndBuilder() {
        User built = User.builder().id(1L).name("Ada").email("ada@example.com").build();
        User constructed = new User(1L, "Ada", "ada@example.com");

        assertEquals(built, constructed);
        assertEquals("Ada", built.getName());

        constructed.setName("Grace");
        assertEquals("Grace", constructed.getName());
    }

    @Test
    void valueClassIsImmutableWithGetters() {
        Address address = new Address("1 Main St", "Springfield");
        assertEquals("Springfield", address.getCity());
    }
}
EOF
cat > .gitignore <<'EOF'
target/
*.iml
.idea/
.vscode/
.classpath
.project
.settings/
EOF
mvn -q -B verify 2>&1 | tail -30; echo exit=$?

